<script setup lang="ts">
definePageMeta({ layout: 'admin' });
const route=useRoute();const q=computed(()=>String(route.query.q||'').trim().toLowerCase());const api=useApi();const resources=[['Jogos','games','/admin/jogos'],['Equipas','teams','/admin/equipas'],['Eventos','events','/admin/eventos'],['Galeria','gallery','/admin/galeria'],['Plantel','players','/admin/plantel'],['Equipa Técnica','staff','/admin/equipa-tecnica'],['Direção','board','/admin/direcao'],['Sócios','members','/admin/socios'],['Patrocínios','sponsors','/admin/patrocinios'],['Oportunidades','opportunities','/admin/oportunidades']];const {data:results,pending}=await useAsyncData('cms-search-'+q.value,async()=>{if(!q.value)return[];const out:any[]=[];for(const [label,res,to] of resources){const rows=await api<any[]>(`/api/${res}`);for(const row of rows){if(JSON.stringify(row).toLowerCase().includes(q.value))out.push({label,to,row})}}return out})</script>
<template><div class="page-stack"><header class="page-heading"><div><p class="eyebrow">Pesquisa</p><h1>Resultados para “{{route.query.q}}”</h1></div></header><div v-if="pending" class="cms-loading">A pesquisar…</div><section v-else class="panel"><div v-if="!results?.length" class="empty-state"><h3>Sem resultados</h3><p>Não foi encontrado conteúdo correspondente.</p></div><div v-else class="table-scroll"><table class="data-table"><tbody><tr v-for="(item,i) in results" :key="i"><td><strong>{{item.label}}</strong></td><td>{{item.row.name||item.row.nome||item.row.title||item.row.jornada||item.row.id}}</td><td><NuxtLink :to="item.to" class="text-button">Abrir <Icon name="lucide:arrow-right"/></NuxtLink></td></tr></tbody></table></div></section></div></template>
